<script setup lang="ts">
import draggable from 'vuedraggable'
import type { MenuItem } from '@olps/domain'
const props=defineProps<{modelValue:MenuItem[];locale:string;targets:Array<{ref:'page'|'collection'|'group'|'item';id:string;title:string}>}>()
const emit=defineEmits<{'update:modelValue':[MenuItem[]]}>()
function add(){const target=props.targets[0];emit('update:modelValue',[...props.modelValue,{menuItemId:crypto.randomUUID(),label:{[props.locale]:'新菜单项目'},link:target?{kind:'internal',target:{ref:target.ref,id:target.id}}:{kind:'external',url:'https://example.com',newWindow:false},children:[]}])}
function select(item:MenuItem,value:string){const target=props.targets.find(target=>`${target.ref}:${target.id}`===value);if(target)item.link={kind:'internal',target:{ref:target.ref,id:target.id}}}
function targetValue(item:MenuItem){return item.link.kind==='internal'?`${item.link.target.ref}:${item.link.target.id}`:''}
function external(item:MenuItem){item.link={kind:'external',url:'https://',newWindow:false}}
</script>
<template><div class="menu-editor"><draggable :model-value="modelValue" item-key="menuItemId" group="website-menu" handle=".drag-handle" @update:model-value="emit('update:modelValue',$event)"><template #item="{element:item}"><article><button type="button" class="secondary drag-handle" aria-label="拖动菜单项目">拖动排序</button><label>菜单文字<input v-model="item.label[locale]" required /></label><label>网站内容<select :value="targetValue(item)" @change="select(item,($event.target as HTMLSelectElement).value)"><option value="">选择网站内容</option><option v-for="target in targets" :key="`${target.ref}:${target.id}`" :value="`${target.ref}:${target.id}`">{{ target.title }}</option></select></label><button v-if="item.link.kind==='internal'" type="button" class="secondary" @click="external(item)">改为外部链接</button><template v-if="item.link.kind==='external'"><label>外部网址<input v-model="item.link.url" type="url" required /></label><label><input v-model="item.link.newWindow" type="checkbox" />在新窗口打开</label></template><button type="button" class="secondary" @click="emit('update:modelValue',modelValue.filter(entry=>entry.menuItemId!==item.menuItemId))">删除菜单项目</button><CmsMenuEditor v-model="item.children" :locale="locale" :targets="targets" /></article></template></draggable><button type="button" class="secondary" @click="add">添加菜单项目</button></div></template>
<style scoped>article{border:1px solid #dbe2ea;padding:14px;margin:12px 0;border-radius:10px}.menu-editor .menu-editor{margin-left:20px}label{display:grid;gap:6px;margin:10px 0}input:not([type=checkbox]),select{padding:8px;width:100%}button{margin:6px 8px 6px 0}</style>
